class NodeType(type):
    """A metaclass for nodes that handles the field and attribute
    inheritance.  fields and attributes from the parent class are
    automatically forwarded to the child."""

    def __new__(mcs, name, bases, d):  # type: ignore
        for attr in "fields", "attributes":
            storage: t.List[t.Tuple[str, ...]] = []
            storage.extend(getattr(bases[0] if bases else object, attr, ()))
            storage.extend(d.get(attr, ()))
            assert len(bases) <= 1, "multiple inheritance not allowed"
            assert len(storage) == len(set(storage)), "layout conflict"
            d[attr] = tuple(storage)
        d.setdefault("abstract", False)
        return type.__new__(mcs, name, bases, d)


def _resolve_eval_context_defaults(
    environment: "Environment",
) -> t.Tuple[t.Any, t.Type[t.Any], bool]:
    """Retrieve evaluation defaults for creating an EvalContext.

    Prefers the registered eval config when available, falling back
    to direct environment attribute access for compatibility.

    Returns (autoescape_setting, undefined_class, has_finalize).
    """
    from .environment import get_eval_config

    config = get_eval_config(id(environment))
    if config is not None:
        return (
            config["autoescape_setting"],
            config["undefined_class"],
            config["has_finalize"],
        )
    return (
        environment.autoescape,
        environment.undefined,
        environment.finalize is not None,
    )


class EvalContext:
    """Holds evaluation time information.  Custom attributes can be attached
    to it in extensions.
    """

    def __init__(
        self, environment: "Environment", template_name: t.Optional[str] = None
    ) -> None:
        self.environment = environment
        autoescape_setting, undefined_class, has_finalize = \
            _resolve_eval_context_defaults(environment)
        if callable(autoescape_setting):
            self.autoescape = autoescape_setting(template_name)
        else:
            self.autoescape = autoescape_setting
        self._eval_undefined = undefined_class
        self._eval_has_finalize = has_finalize
        self.volatile = False

    def save(self) -> t.Mapping[str, t.Any]:
        return self.__dict__.copy()

    def revert(self, old: t.Mapping[str, t.Any]) -> None:
        self.__dict__.clear()
        self.__dict__.update(old)


def get_eval_context(node: "Node", ctx: t.Optional[EvalContext]) -> EvalContext:
    if ctx is None:
        if node.environment is None:
            raise RuntimeError(
                "if no eval context is passed, the node must have an"
                " attached environment."
            )
        return EvalContext(node.environment)
    return ctx


